(function () {
  const LIVE_STATUS_URL =
    "https://raw.githubusercontent.com/OnsKasteeltje/homey-energy-manual/main/docs/data/homey-status.json";

  const statusLabels = {
    active: "Actief",
    shadow: "Shadow/Test",
    off: "Uit",
    error: "Fout",
    unknown: "Onbekend"
  };

  const statusClass = (s) =>
    ["active", "shadow", "off", "error"].includes(s) ? `status-${s}` : "status-unknown";

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }

  async function fetchJson(url) {
    const u = new URL(url, document.baseURI);
    u.searchParams.set("_", Date.now());
    const response = await fetch(u, { cache: "no-store" });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return response.json();
  }

  async function loadStatus() {
    const dashboard = document.getElementById("homey-flow-dashboard");
    const update = document.getElementById("homey-last-update");
    const health = document.getElementById("homey-sync-health");
    if (!dashboard) return;

    let data;
    try {
      try {
        data = await fetchJson(LIVE_STATUS_URL);
      } catch (_) {
        data = await fetchJson("data/homey-status.json");
      }

      dashboard.innerHTML = "";
      for (const flow of (data.flows || [])) {
        const status = flow.status || (flow.broken ? "error" : flow.enabled ? "active" : "off");
        const card = document.createElement("article");
        card.className = `flow-card ${statusClass(status)}`;
        card.innerHTML = `
          <div class="flow-card-header">
            <div>
              <div class="flow-category">${escapeHtml(flow.category || "Flow")}</div>
              <div class="flow-card-title">${escapeHtml(flow.name)}</div>
            </div>
            <span class="status-pill ${statusClass(status)}">● ${escapeHtml(statusLabels[status] || statusLabels.unknown)}</span>
          </div>
          <div class="flow-detail">${escapeHtml(flow.detail || "")}</div>
          <div class="flow-meta">
            <span>Enabled: <strong>${flow.enabled ? "ja" : "nee"}</strong></span>
            <span>Broken: <strong>${flow.broken ? "ja" : "nee"}</strong></span>
          </div>
        `;
        dashboard.appendChild(card);
      }

      const dt = data.generated_at ? new Date(data.generated_at) : null;
      update.textContent = dt && !Number.isNaN(dt.getTime())
        ? `Laatst gesynchroniseerd: ${dt.toLocaleString("nl-NL")} · bron: ${data.source || "Homey"}`
        : "Synchronisatietijd onbekend";

      if (data.sync_ok === false) {
        health.className = "health-badge health-error";
        health.textContent = "● synchronisatiefout";
      } else {
        health.className = "health-badge health-ok";
        health.textContent = "● synchronisatie OK";
      }
    } catch (error) {
      dashboard.innerHTML = `
        <article class="flow-card status-error">
          <div class="flow-card-title">Homey-status kon niet worden geladen</div>
          <div class="flow-detail">${escapeHtml(error.message)}</div>
        </article>`;
      update.textContent = "Geen actuele synchronisatie beschikbaar";
      health.className = "health-badge health-error";
      health.textContent = "● synchronisatiefout";
    }
  }

  document.addEventListener("DOMContentLoaded", loadStatus);
  document.addEventListener("DOMContentSwitch", loadStatus);
})();

.status-toolbar {
  display:flex; align-items:center; justify-content:space-between; gap:1rem;
  padding:1rem 1.1rem; margin:1rem 0 1.25rem; border:1px solid var(--md-default-fg-color--lightest);
  border-radius:.8rem; background:var(--md-code-bg-color);
}
.muted { opacity:.7; font-size:.86rem; }
.flow-grid {
  display:grid; grid-template-columns:repeat(auto-fit,minmax(280px,1fr)); gap:1rem; margin:1rem 0 1.5rem;
}
.flow-card {
  border:1px solid var(--md-default-fg-color--lightest); border-left:5px solid #999;
  border-radius:.8rem; padding:1rem; background:var(--md-default-bg-color);
  box-shadow:0 2px 8px rgba(0,0,0,.04);
}
.flow-card.status-active { border-left-color:#2e7d32; }
.flow-card.status-shadow { border-left-color:#f9a825; }
.flow-card.status-off { border-left-color:#757575; opacity:.88; }
.flow-card.status-error { border-left-color:#c62828; }
.flow-card-header { display:flex; justify-content:space-between; gap:.75rem; align-items:flex-start; }
.flow-category { text-transform:uppercase; letter-spacing:.06em; opacity:.62; font-size:.7rem; margin-bottom:.2rem; }
.flow-card-title { font-weight:700; line-height:1.25; }
.flow-detail { margin:.75rem 0; font-size:.9rem; opacity:.84; }
.flow-meta { display:flex; gap:1rem; font-size:.78rem; opacity:.7; }
.status-pill, .health-badge {
  display:inline-block; padding:.25rem .55rem; border-radius:999px; font-size:.76rem; font-weight:700; white-space:nowrap;
}
.status-pill.status-active, .health-ok { background:rgba(46,125,50,.13); color:#2e7d32; }
.status-pill.status-shadow { background:rgba(249,168,37,.16); color:#b26a00; }
.status-pill.status-off { background:rgba(117,117,117,.14); color:#616161; }
.status-pill.status-error, .health-error { background:rgba(198,40,40,.13); color:#c62828; }
.status-pill.status-unknown, .health-unknown { background:rgba(90,90,90,.12); color:#666; }
.legend { display:flex; flex-wrap:wrap; gap:.5rem; margin:.75rem 0; }
@media (max-width: 600px) {
  .status-toolbar { align-items:flex-start; flex-direction:column; }
  .flow-card-header { flex-direction:column; }
}
